#include <cstddef>
#include <vector>

template <typename T>
T maxOf(T only)
{
    return only;
}

template <typename T, typename... Rest>
T maxOf(T first, Rest... rest)
{
    const T others{ maxOf(rest...) };
    return first > others ? first : others;
}

template <typename T, typename... Options>
bool isOneOf(const T& value, const Options&... options)
{
    return ((value == options) || ...);
}

template <typename T, typename... Values>
std::size_t pushAll(std::vector<T>& target, const Values&... values)
{
    (target.push_back(values), ...);
    return sizeof...(Values);
}

unitTests:
TEST("maxOf") { CHECK_EQ(maxOf(3), 3); CHECK_EQ(maxOf(3, 9, 4), 9); CHECK_EQ(maxOf(9, 3, 4, 1), 9); CHECK_EQ(maxOf(1, 2, 3, 4, 50), 50); CHECK_NEAR(maxOf(1.5, 0.5), 1.5, 1e-12); }
TEST("isOneOf") { const std::string cmd{ "quit" }; CHECK(isOneOf(cmd, "exit", "quit", "q")); CHECK(!isOneOf(cmd, "go", "stop")); CHECK(isOneOf(3, 1, 2, 3)); CHECK(!isOneOf(3)); }
TEST("pushAll") { std::vector<int> v{ 1 }; CHECK_EQ(pushAll(v, 2, 3, 4), 3u); CHECK_EQ(v, (std::vector<int>{ 1, 2, 3, 4 })); CHECK_EQ(pushAll(v), 0u); CHECK_EQ(v.size(), 4u); }

